insert into public.reg_area (id, authority, kind, name, parent_id, boundary_geojson, source_url, verified_at, notes) values
  ('ak-se-state', 'adfg', 'ocean_region', 'Southeast Alaska — state waters (Cape Fairweather to Dixon Entrance, shoreline to 3 nm)', null, '[[-139.3,57.4],[-136.8,56.4],[-135.9,58],[-136.5,59.4],[-139,59.9],[-139.4,59.6],[-139.3,57.4]]', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', '2026-09-02', 'Envelope of the Southeast saltwater general area. State waters run shoreline to 3 nautical miles; beyond that is the EEZ — see the EEZ doctrine row. Management-area exceptions (Juneau/Glacier Bay, Sitka, Petersburg/Wrangell, Ketchikan) live in the booklet''s special section — not shipped yet.'),
  ('ak-se-eez', 'adfg', 'ocean_region', 'Southeast Alaska — EEZ (3–200 nautical miles offshore)', null, null, 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', '2026-09-02', 'Marker area: ADF&G''s booklet applies NONRESIDENT bag/possession/annual limits and nonresident lingcod size limits to all anglers in the EEZ.')
on conflict (id) do nothing;

