insert into public.reg_rule
  (species_id, reg_group_id, reg_area_id, water_class, kind, verbatim, source_url, source_title, source_updated_at, verified_at, pack_version,
   season_start, season_end, bag_daily, possession_limit, min_size_in, max_size_in, size_measure, platform_scope, depth_note, check_inseason, stale_after_days)
values
  (null, null, 'ak-se-state', 'salt', 'note', 'The salt water sport fishing season is open year-round for all species, except for halibut, lingcod, demersal shelf rockfish, Tanner crab, shrimp, and resident king crab fisheries, and unless otherwise noted below or in special regulations. Stay legal — before you cast, check emergency orders at www.adfg.alaska.gov/sf/EONR.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 30),
  (null, null, 'ak-se-state', 'salt', 'note', 'Other fish species not listed on pages 10-13: No bag, possession, annual, or size limits.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, false, 120),
  ('chinook_salmon', null, 'ak-se-state', 'salt', 'note', 'King salmon — Southeast Alaska salt water: 28 inches or longer: Bag, possession, annual, and size limits are established annually by an emergency order, as specified in the Southeast Alaska King Salmon Management Plan. Nonresidents: A harvest record is required. Charter operators and their crew are prohibited from keeping king salmon while clients are on board.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 7),
  ('chinook_salmon', null, 'ak-se-state', 'salt', 'prohibited', 'King salmon — Southeast Alaska salt water: Less than 28 inches: Retention prohibited.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 0, 0, 28, null, 'total_length', null, null, true, 7),
  (null, 'akse-4salmon', 'ak-se-state', 'salt', 'bag_limit', 'Chum, coho, pink, & sockeye salmon — salt water: 16 inches or longer: 6 of each species per day, 12 of each species in possession. Less than 16 inches: 10 per day, 10 in possession, in combination.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 6, 12, null, null, null, null, null, true, 30),
  ('pacific_halibut', null, 'ak-se-state', 'salt', 'season', 'Halibut — Southeast Alaska salt water: January 1-January 31: Closed to halibut fishing. February 1-December 31: Open to halibut fishing.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   '2026-01-01', '2026-01-31', 0, null, null, null, null, null, null, true, 30),
  ('pacific_halibut', null, 'ak-se-state', 'salt', 'bag_limit', 'Unguided anglers: 2 per day, 4 in possession, no size limit. Pacific halibut fisheries are managed by the federal government under international treaty. Possession includes unpreserved AND preserved fish for halibut. Proxy fishing for halibut is not allowed.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   '2026-02-01', '2026-12-31', 2, 4, null, null, null, null, null, true, 14),
  ('pacific_halibut', null, 'ak-se-state', 'salt', 'note', 'Consult federal regulations for the following: bag, size, and possession limits for guided (charter) anglers; possession and landing requirements, and inseason changes to the regulations. Federal halibut regulations are available through NOAA Fisheries Alaska Region at (907) 586-7228. www.alaskafisheries.noaa.gov/fisheries/sport-halibut. No person shall possess on board a vessel Pacific halibut that have been filleted, mutilated, or otherwise disfigured in any manner, except that each Pacific halibut may be cut into no more than 2 ventral pieces, 2 dorsal pieces, and 2 cheek pieces, with a patch of skin on each piece, naturally attached.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 14),
  ('lingcod', null, 'ak-se-state', 'salt', 'season', 'Lingcod — Alaska Residents (All areas): May 16-November 30: Open to lingcod fishing. 1 per day, 2 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   '2026-05-16', '2026-11-30', 1, 2, null, null, null, null, null, true, 30),
  ('lingcod', null, 'ak-se-state', 'salt', 'note', 'Lingcod — Nonresidents (All areas except Yakutat area): 1 per day, 1 in possession. There is an annual limit of 2 fish, 1 that is 30-35 inches long, and 1 that is 55 inches or longer. Harvest record required. Charter operators and their crew are prohibited from keeping lingcod while clients are on board. Northern Southeast Area: May 16-June 14 and September 1-November 30. Central Southeast Outside Area: May 16-June 30 and September 1-November 30. Southern Southeast Outer Coast Area: May 16-July 31 and September 1-November 30. Southern Southeast Inside Waters Area: May 16-November 30. Yakutat Area: May 16-November 30.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 14),
  (null, 'akse-pelagic-rockfish', 'ak-se-state', 'salt', 'bag_limit', 'Pelagic rockfish includes black, dark, deacon, dusky, widow, and yellowtail. These six species are uniformly gray, green, brown, or black: 3 per day, 6 in possession, no size limit, except Sitka Area (CSEO). See page 25.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 3, 6, null, null, null, null, null, true, 30),
  (null, 'akse-slope-rockfish', 'ak-se-state', 'salt', 'bag_limit', 'Slope rockfish includes blackgill, blackspotted, blue, bocaccio, brown, chilipepper, darkblotched, greenstriped, harlequin, northern, Pacific Ocean perch, Puget Sound, pygmy, redstripe, redbanded, rougheye, sharpchin, shortbelly, shortraker, silvergray, splitnose, stripetail, vermilion, and yellowmouth: 1 per day, 2 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 1, 2, null, null, null, null, null, true, 30),
  (null, 'akse-dsr', 'ak-se-state', 'salt', 'bag_limit', 'Demersal shelf rockfish includes canary, China, copper, quillback, rosethorn, tiger, and yelloweye. Alaska Residents: 1 per day, 2 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 1, 2, null, null, null, null, null, true, 30),
  (null, 'akse-dsr', 'ak-se-state', 'salt', 'note', 'Demersal shelf rockfish — Nonresidents: July 1-August 25: Open to demersal shelf rockfish fishing. 1 per day, 1 in possession, no size limit. There is an annual limit of 1 fish. Harvest record required.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 14),
  ('yelloweye_rockfish', 'akse-dsr', 'ak-se-state', 'salt', 'season', 'Demersal shelf rockfish — Nonresidents: July 1-August 25: Open to demersal shelf rockfish fishing. (Outside July 1-August 25, nonresidents may not retain demersal shelf rockfish.)', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   '2026-07-01', '2026-08-25', null, null, null, null, null, null, null, true, 14),
  ('rockfish', null, 'ak-se-state', 'salt', 'note', 'All vessels must have at least one functional deepwater release device on board and readily available for use when sport fishing activities are taking place regardless of species targeted. All rockfish not retained must be released at the depth they were caught or 100 feet, whichever is shallower. Upon request, a deepwater release device must be presented to a local representative of ADF&G or a peace officer of the state.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, 'boat', null, false, 120),
  ('sablefish', null, 'ak-se-state', 'salt', 'bag_limit', 'Sablefish (black cod): Alaska residents: 6 per day, 6 in possession, no size limit. Nonresidents: 4 per day, 4 in possession, no size limit. There is a 8 fish annual limit, harvest record required.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, 6, 6, null, null, null, null, 'Nonresidents: 4 per day, 4 in possession, annual limit 8.', true, 30),
  (null, null, 'ak-se-state', 'salt', 'note', 'Sharks (except spiny dogfish): 1 per day, 1 in possession, no size limit. There is a 2 shark annual limit, harvest record required. Spiny dogfish: 5 per day, 5 in possession, no size limit, harvest record is NOT required.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 60),
  (null, null, 'ak-se-eez', 'salt', 'note', 'Exclusive Economic Zone waters (all saltwaters 3 to 200 nautical miles from the shoreline): Nonresident bag, possession, and annual limits apply to ALL anglers; nonresident lingcod size limits apply; nonresident seasonal closures apply; harvest record required for king salmon, lingcod, demersal shelf rockfish, sablefish, steelhead trout, and sharks. Anglers may only possess the limit of fish allowed for the specific waters they are fishing.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southeast/2026se_sfregs_general_freshwater_saltwater.pdf', 'ADF&G — 2026 Southeast Alaska Sport Fishing Regulations Summary Book (General Regulations: Salt Water)', null, '2026-09-02', 1,
   null, null, null, null, null, null, null, null, null, true, 30);

insert into public.reg_pack (id, version, published_at, notes) values
  ('alaska-2026-09-02', 1, '2026-09-02T18:00:00Z', 'Alaska — Southeast (ADF&G 2026 Region 1 summary book): saltwater year-round except halibut/lingcod/DSR/crab/shrimp. Lingcod May 16–Nov 30 w/ nonresident 30–35 in-or-55 in+ slot and 2/yr; DSR nonresidents Jul 1–Aug 25 only, annual 1; halibut closed January, unguided 2/day; pelagic 3 / slope 1 / DSR 1 rockfish regimes; deepwater release device mandatory; EEZ switches everyone to nonresident limits. Emergency orders control king salmon annually.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

